          "items": {
            "type": "object",
            "description": "单条餐厅排队或预约日程。",
            "properties": {
              "entityName": {
                "type": "string",
                "description": "日程实体类别。",
                "sampleValue": "日历事件"
              },
              "entityId": {
                "type": "string",
