                "sampleValue": "calendar-queue-001"
              },
              "title": {
                "type": "string",
                "description": "餐厅排队或预约日程标题。",
                "sampleValue": "海港餐厅排队"
              },
              "eventLocation": {
                "type": "string",
                "description": "排队或预约地点。",
                "sampleValue": "海港餐厅"
              },
              "description": {
                "type": "string",
