                "sampleValue": "当前叫到 A116，前方 3 桌，请尽快到店。"
              },
              "dtStart": {
                "type": "string",
                "description": "预计开始或到店时间。",
                "sampleValue": "18:30"
              },
              "dtEnd": {
                "type": "string",
                "description": "预计结束时间。",
                "sampleValue": "19:10"
              }
            }
          }
        }
      }
    },
    "queue": {
      "number": {
        "type": "string",
        "description": "餐厅排队号展示文本。",
        "sampleValue": "A128"
      },
      "status": {
        "type": "string",
        "description": "红色警告状态文案。",
        "sampleValue": "即将叫号"
      },
      "aheadCountText": {
        "type": "string",
        "description": "前方等待桌数展示文本。",
        "sampleValue": "前方 3 桌"
      },
      "etaText": {
        "type": "string",
        "description": "预计叫号时间展示文本。",
        "sampleValue": "约 18:30"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_schedule.png",
      "description": "日程图标，适合表达从日历读取的当下餐厅排队预约信息，可作为图片叠字的视觉锚点。"
    },
    {
      "src": "resources/base/media/icon_time.png",
      "description": "时间图标，适合辅助表达预计叫号或到店时间。"
    }
  ]
}

